function lessonForUser(lessonId, user) { const lesson = one('SELECT l.id,l.status,c.class_level,c.published,c.teacher_id FROM lessons l JOIN chapters ch ON ch.id=l.chapter_id JOIN courses c ON c.id=ch.course_id WHERE l.id=?', lessonId); if (!lesson) return null; if (user.role === 'admin' || (user.role === 'teacher' && lesson.teacher_id === user.id)) return lesson; if (user.role === 'student' && lesson.status === 'published' && lesson.published && lesson.class_level === user.classLevel && (!one('SELECT 1 FROM lesson_assignments WHERE lesson_id=? LIMIT 1', lessonId) || one('SELECT 1 FROM lesson_assignments WHERE lesson_id=? AND student_id=?', lessonId, user.id))) return lesson; return null }
