async function serveFrontend(request, response) {
  if (!['GET', 'HEAD'].includes(request.method)) return json(response, 405, { error: 'Method not allowed.' })
  const pathname = decodeURIComponent(new URL(request.url, `http://${request.headers.host}`).pathname)
  const relativePath = pathname === '/' ? 'index.html' : pathname.replace(/^[/\\]+/, '')
  const candidate = resolve(distDirectory, relativePath)
  const safeCandidate = candidate === distDirectory || candidate.startsWith(`${distDirectory}${sep}`)
  const filePath = safeCandidate && existsSync(candidate) && (await stat(candidate)).isFile() ? candidate : resolve(distDirectory, 'index.html')
  if (!existsSync(filePath)) return json(response, 503, { error: 'Frontend build not found. Run npm run build before starting the production server.' })
  response.writeHead(200, { 'Content-Type': mimeTypes[extname(filePath).toLowerCase()] || 'application/octet-stream', 'Cache-Control': filePath.endsWith('index.html') ? 'no-cache' : 'public, max-age=31536000, immutable' })
  if (request.method === 'HEAD') return response.end()
  createReadStream(filePath).pipe(response)
}

async function application(request, response) {
  const path = new URL(request.url, `http://${request.headers.host}`).pathname
  if (path === '/api' || path.startsWith('/api/')) return route(request, response)
  return serveFrontend(request, response)
}

